Section CL.
  Variables (ra sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  (* [comment removed for export] *)
  Variables (x9 x10 x11 x13 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word).
  Variables (m : fmem) (HW RK : Z) (ws : list Z).
  Variable POST : machine_state -> Prop.
  Hypothesis HWS : 1 <= zlen ws <= 255.
  Hypothesis HWB : Forall (fun c => 0 <= c < 256) ws.
  Hypothesis HHW : 0 < HW /\ HW + 256 <= 2^64.
  Hypothesis HRK : 0 < RK /\ RK + 52 <= 2^64.
  Hypothesis DHR : HW + 256 <= RK \/ RK + 52 <= HW.

  (* [comment removed for export] *)
  Definition cl_inv (m1 : fmem) (rank : list Z) : Prop :=
    u32arr psegs m1 RK (map (Z_to_bv 64) rank)
    /\ bytes_at psegs m1 HW (map (Z_to_bv 8) ws)
    /\ munch [(RK, RK + 52)] m m1 /\ wmono psegs m m1 /\ mem_inv psegs m1.

  (* [comment removed for export] *)
  Definition cl_ok (n : Z) (rank : list Z) (wt : Z) : Prop :=
    zlen rank = 13 /\ Forall (fun v => 0 <= v <= n) rank /\ 0 <= wt <= n * 2048.

  Notation ST pc mm x5 x6 x7 x14 x17 :=
    (MS (mkR ra sp gp tp x5 x6 x7 (Z_to_bv 64 RK) x9 x10 x11 (Z_to_bv 64 HW) x13 x14 (Z_to_bv 64 1) (Z_to_bv 64 12) x17
             (Z_to_bv 64 (zlen ws)) x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  Lemma cl_loop : forall f n rank wt m1 (x6 x7 : word),
    Z.of_nat f = zlen ws - n -> 0 <= n < zlen ws ->
    cl_ok n rank wt -> cl_inv m1 rank ->
    (forall m2 rank' wt' (y5 y6 y7 y17 : word),
       collect_loop (skipn (Z.to_nat n) ws) rank wt = Ok (rank', wt') -> cl_ok (zlen ws) rank' wt' -> cl_inv m2 rank' ->
       evt psegs POST (ST 0x1b6e4 m2 y5 y6 y7 (Z_to_bv 64 wt') y17)) ->
    (forall m2 rank' (y5 y6 y7 y14 y17 : word),
       collect_loop (skipn (Z.to_nat n) ws) rank wt = Err ZSTD_error_corruption_detected -> cl_inv m2 rank' ->
       evt psegs POST (ST 0x1b84c m2 y5 y6 y7 y14 y17)) ->
    evt psegs POST (ST 0x1b6a4 m1 (Z_to_bv 64 n) x6 x7 (Z_to_bv 64 wt) (Z_to_bv 64 (n + 1))).
Proof.
